INSERT INTO fut_evolution_unlocks VALUES(1,2489,1,'2026-10-09','반복 배급(Repeat Delivery) 사용권 1회 추가 획득 — 미션 달성(해금 문구 「EVO Ascension」) · 사용자 보고 2026-10-09. 이 진화는 최대 4회(repeatability=4)이고 이전 3회 사용(알리송·지모-알로바·바르가스) → 이번이 4번째(마지막) 사용권. 마감 2026-10-22 16:00 KST · [2026-10-09] 티아고 페르난데스(레반테 74)에 사용 — 소진');
