INSERT INTO fut_evolution_unlocks VALUES(1,2610,1,'2026-11-04','Channel Surfer [SP 11] 아직 미해금 — 사용자 보고 2026-10-31 「채널서퍼는 아직 못 얻었어」 · 해금 문구 「Unlocked by reaching level 11 in the Standard Season Pass」 · ⚠️ 10-13 기록의 SP 27은 시즌 1 패스로 보인다(시즌 2 10-22 시작 · 이 진화는 시즌 2 패스 레벨 기준으로 추정 — 미확인) · 부엔디아는 False Seven을 이미 시작해(10-31) OVR 81이 되면 이 진화(OVR ≤80) 대상에서 빠진다 ‖ [2026-11-04 해금] 사용자 「측면질주 진화 해금했어」 — 인게임 한국어 이름 「측면질주」 = Channel Surfer [SP 11](사용자 확인) · 아직 미적용 · 1회성 · 마감 2026-12-10 18:00 UTC · 조건 OVR ≤80 · LM/LW · ST·LB 보유 제외 · PS ≤7 · PAC ≤86 → OVR +7(^83) · Rapid·Press Proven · 드리블·속도·마무리 계열 +10. 빌라 보유 카드 중 조건 통과 0장(Alysson RM/RW · 마첸 LB 보유 · 나머지 OVR 81+) · 보유 전체 후보: Jack Moylan 80 · Mateus Mané 80 · 오베드 바르가스 78 · Gheorghiță 64 (민테 PAC 93·Toma PAC 87은 속도 상한 초과) — 포지션 조건이 주 포지션 기준인지 보조 포함인지는 미확인.');
INSERT INTO fut_evolution_unlocks VALUES(1,2622,1,'2026-11-01','The Haunted Wall(공포의 벽) 해금 — 사용자 보고 2026-11-01 「우선 공포의 벽은 해금했어 좀 지켜보다가 나중에 업글할께」 · 아직 어느 선수에게도 적용 안 함 · 1회성 · 무료 · 마감 2026-11-27 18:00 UTC · OVR ≤81 · PS ≤7 · PAC ≤85 → OVR +8(^84) · 수비·피지컬·속도 상승 · 4단계 PS 선택(Bruiser/Intercept/Anticipate) · Ultimate Scream 레어도 · 후보 시세(계산 CB OVR 76.1→80.3 · 표기 78→84)');
